def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    class Err(Exception):
        pass

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def parse_sum() -> int:
        nonlocal i
        left = parse_product()
        while True:
            skip()
            if i < n and s[i] in "+-":
                op = s[i]
                i += 1
                right = parse_product()
                left = left + right if op == "+" else left - right
            else:
                break
        return left

    def parse_product() -> int:
        nonlocal i
        left = parse_unary()
        while True:
            skip()
            if i < n and s[i] in "*/%":
                op = s[i]
                i += 1
                right = parse_unary()
                if op == "*":
                    left *= right
                else:
                    if right == 0:
                        raise Err()
                    q = abs(left) // abs(right)
                    if (left < 0) != (right < 0):
                        q = -q
                    left = q if op == "/" else left - right * q
            else:
                break
        return left

    def parse_unary() -> int:
        nonlocal i
        skip()
        if i < n and s[i] == "-":
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power() -> int:
        nonlocal i
        left = parse_primary()
        skip()
        if i < n and s[i] == "^":
            i += 1
            right = parse_unary()
            if right < 0:
                raise Err()
            return left ** right
        return left

    def parse_primary() -> int:
        nonlocal i
        skip()
        if i < n and s[i] == "(":
            i += 1
            val = parse_sum()
            skip()
            i += 1
            return val
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    try:
        return parse_sum()
    except Err:
        return "error"
